export function installNPC(card,raw,H){
 const{hit:d,st:s,shield:z,heal:h,energy:e,gauge:q,summon:p,special:x}=H,a=(n,hits=1)=>d(n,'A','physical',{hits}),buff=(name,values,to='self',duration=2)=>({op:'buff',name,values,to,duration});
 const delayed=(effects,all=false)=>({op:'delayed',turns:1,effects,all}),cond=(name,yes,no)=>({op:'if',test:{status:name},effects:yes,otherwise:no});
 const defs={
 soldier:[[a(1.3)],[z(.1,'allies')]],crossbow:[[a(1.5)]],caster:[[d(1.6)],[d(1),s('沉默',1,1)]],heavy:[[a(1.4),q(-60)],[z(.2),s('嘲讽',1,2,'self')]],host:[[a(1.6),{op:'life',ratio:.04}]],ragehost:[[a(2.2),{op:'life',ratio:.06}]],yeti:[[d(1.4),s('寒冷')],[z(.1,'allies')]],breaker:[[{op:'if',test:{anyStatus:['寒冷','冻结']},effects:[a(2.6)],otherwise:[a(1.8)]}]],herald:[[buff('作战号令',{A:.2},'allies')]],shield:[[z(.25),s('嘲讽',1,2,'self')],[a(1.7)]],drone:[[delayed([a(2)])]],deep:[[a(1.5)]],flame:[[d(1.5),s('灼烧')]],sarkaz:[[a(1.6),s('破防')]],sarkazmage:[[d(1.7),q(-60)]],bloodling:[[a(1.4),h(.06)]],rotguard:[[a(1.8),s('凋亡',1,3)]],
 dobermann:[[a(1.5)],[z(.15,'ally'),buff('鞭策',{A:.25},'ally')]],amiya:[[d(1.6)],[buff('战术咏唱',{P:.2})]],nearl:[[h(.2,'ally')],[h(.12,'allies'),s('嘲讽',1,2,'self')]],ace:[[z(.15,'allies'),s('嘲讽',1,2,'self')],[a(1.8)]],chen:[[a(1),d(.8)],[a(1,3),s('眩晕',1,1)]],hoshi:[[z(.25),s('嘲讽',1,2,'self')],[a(2)]],frostleaf:[[a(1.4),s('寒冷')],[a(1.1),q(-60)]],jessica:[[a(1.7)],[buff('烟幕闪避',{dodge:1},'allies')]],meteorite:[[a(1.7)],[a(2),s('破防')]],blaze:[[a(1.8)],[a(2.4),{op:'life',ratio:.1}]],rosmontis:[[d(1.8,'P','physical')],[p('战术设备',.2,0,'P',2,3,{count:2,facility:true,taunt:true}),d(2.6,'P','physical')]],amiya_sword:[[a(2),d(1)],[d(.9,'P','true',{hits:3}),{op:'life',ratio:.12}]],bagpipe:[[a(1.1,2)],[a(1.1,3),z(.15)]],saileach:[[e(12,'allies')],[h(.2,'ally'),z(.15,'ally')]],horn:[[a(1.7),x('reveal'),{op:'mark',name:'禁匿',n:1,duration:2}],[a(2.3),{op:'life',ratio:.08}]],siege:[[a(1.9),q(-60)],[a(2.6),s('眩晕',1,1)]],heidi:[[buff('怒士',{A:.15,P:.15},'allies')],[z(.15,'allies')]],ines:[[a(1.5),q(-60),x('reveal')],[a(2.2),s('迷彩',1,1,'self')]],hoederer:[[a(2.2)],[a(3),h(.15)]],logos:[[d(2),s('沉默',1,1)],[d(1.6),q(-60)],[d(2.8)]],siege_sword:[[a(2),d(.8,'P','true')],[z(.2,'allies'),s('嘲讽',1,2,'self')]],amiya_final:[[h(.15,'allies'),x('cageStrike')],[d(2.2),{op:'cleanse',to:'allies'}]],
 w:[[a(1.7),delayed([a(.8)])],[a(1.8)]],crown:[[a(1.7),s('隐匿',1,1,'self')],[a(2)]],skull:[[a(1.6)],[a(2.4),{op:'life',ratio:.05}]],misha:[[a(1.4)]],meph:[[h(.25,'allies')],[p('宿主士兵',.25,.5,'A',2,99,{host:true})]],faust:[[a(2.6)],[p('幻影弩炮',.25,.5,'A',1,3,{d:.5,r:.5})]],frost:[[d(1.6),s('寒冷')],[delayed([d(2.4)])]],winter:[[d(2),s('寒冷')],[p('雪怪影像',.25,.28,'P',1,2,{d:.5,r:.5,cold:true})],[delayed([d(3)])]],patriot:[[a(1.6,2)],[delayed([a(3.2)])],[x('wendigo')]],bird:[[d(1.2),s('毒',1,3)],[d(1.8),{op:'life',ratio:.05}]],talulah:[[d(1.9),s('灼烧')],[d(2.2)],[delayed([x('fireLine')],true)]],mandragora:[[d(2),s('迟缓')],[z(.25),buff('石之盾',{mitigation:.3})],[d(1.8)]],manfred:[[d(1.8)],[a(1.2),d(1)]],steam:[[buff('蒸汽增压',{A:.25,V:.15})],[a(1,3)],[delayed([a(2.5)])]],cluster:[[d(1.8)],[p('分体',.15,.35,'P',2,3,{count:2,d:.5,r:.5})]],sanguinarch:[[d(1.8),h(.1)],[p('血珀',.08,0,'P',2,99,{hatch:2,d:.25,r:.25})],[d(2.6),h(.2,'allies')]],theresa:[[x('seal')],[x('seal')],[z(.2),d(1.8)]]};
 const row=defs[raw.id];if(!row)throw Error('Unimplemented NPC '+raw.id);
 card.actions.forEach((v,i)=>{v.ops=row[i];if(!v.ops)throw Error(raw.id+' '+v.button);let target=raw.skills[v.button].target;v.target=/召唤|自己$/.test(target)?'self':/全场|敌全体/.test(target)?'enemy_all':/敌二/.test(target)?'enemy_two':/友全体|友二/.test(target)?'ally_all':/友|玩家/.test(target)?'ally_one':'enemy_one';});
 if(raw.id==='logos'){card.actions[2].target='enemy_up_to_three';card.actions[2].ops=[d(3.6),q(-60),z(.18,'allies')];}
 if(raw.id==='amiya_final'){card.actions[0].target='self';card.actions[1].target='enemy_all';}
 if(raw.id==='theresa')card.actions.forEach(v=>v.target=v.button==='C'?'enemy_one':'self');
 card.explicit=true;
}
export const NPC_CYCLES={soldier:['A','martial','B'],ragehost:['A','martial'],shield:['A','B','martial'],deep:['A','martial'],sarkaz:['A','martial'],bloodling:['A','martial'],rotguard:['A','martial','defend'],w:['A','A','B'],misha:['A','martial'],bird:['B','A','rest'],talulah:['A','A','B','C'],frost:['B','A','martial'],winter:['A','B','C'],patriot:['A','martial'],manfred:['A','A','B'],steam:['A','martial','B','C'],theresa:['A','C','B']};
